{
  "name": "deveco-model-plugin",
  "version": "0.1.2",
  "description": "OpenCode plugin for DevEco login and built-in model provider",
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./server": "./dist/index.js",
    "./credentials": {
      "types": "./dist/types/credentials.d.ts",
      "import": "./dist/credentials.js"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "bun build ./src/index.ts ./src/credentials.ts --outdir ./dist --target node --external '@opencode-ai/plugin' && tsc --declaration --emitDeclarationOnly --rootDir src --outDir dist/types",
    "prepublishOnly": "bun run build",
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "license": "MIT",
  "keywords": [
    "opencode",
    "plugin",
    "deveco",
    "harmonyos"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.17.3"
  },
  "devDependencies": {
    "bun-types": "1.3.14",
    "typescript": "^6.0.3"
  },
  "engines": {
    "opencode": ">=1.17.3"
  }
}
